<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · PosterCollage</h1>
      <p class="demo-page__lead">
        来自 video-code 的「火影忍者人物海报页面」：一张 1400×800 的设计稿上摆了 12 张原始人物抠图，各自绝对定位、
        各带一个层级；鼠标移上去那张会放大 1.4 倍并被抬到所有图层之上，移开再落回原位；整张画布按容器
        等比缩放。原 demo 绑的是 <code>window</code> 尺寸，组件改由自己的容器决定，塞进卡片里也能自适应。
      </p>
    </header>

    <section class="poster-demo">
      <div class="poster-demo__head">
        <h2 class="demo-page__section-title">把指针移到任意一张上</h2>
        <code class="poster-demo__tag">{{ layers.length }} 层</code>
      </div>
      <p class="demo-card__text">
        下面这张海报直接使用原 demo 的 12 张人物 PNG，位置和层级也保持一致（鸣人在中间层、宁次压在最前）。
        悬停放大的同时会临时抬高 <code>z-index</code>，所以哪怕被别的抠图挡住也能整张冒出来。
      </p>

      <div class="poster-demo__stage">
        <PosterCollage
          :items="layers"
          :width="1400"
          :height="800"
          :hover-scale="1.4"
          :hover-lift="1000"
          :paper="posterPaper"
          @select="onSelect"
        />
      </div>

      <p class="poster-demo__hint">
        最近点中：<code>{{ lastSelected }}</code>
      </p>

      <div class="poster-demo__row">
        <div class="poster-demo__cell">
          <PosterCollage
            :items="layers.slice(0, 6)"
            :width="1400"
            :height="800"
            :hover-scale="1.12"
            :max-scale="1"
            :paper="posterPaper"
          />
          <p>只放 6 层 + 放大 1.12（<code>hoverScale</code> / <code>maxScale</code>）</p>
        </div>
        <div class="poster-demo__cell">
          <PosterCollage
            :items="layers.slice(6)"
            :width="1400"
            :height="800"
            :hover-scale="1.6"
            :background="backdrop"
          />
          <p>带底图 + 放大 1.6（<code>background</code>），适合直接当宣传图</p>
        </div>
      </div>
    </section>

    <DemoPreview class="poster-preview">
      <LevaPlayground
        name="PosterCollage"
        :component="PosterCollage"
        :schema="PosterCollageSchema"
        :presets="{ items: abstractLayers }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>width</code> / <code>height</code> 是设计稿尺寸（图层的坐标都按这套来），
        <code>background</code> 是铺满整张画布的底图，<code>paper</code> 是底色（可以给渐变），
        <code>hoverScale</code> / <code>hoverLift</code> 是悬停放大倍数和临时抬高的层级，
        <code>maxScale</code> 限制大屏上的缩放上限，<code>clickable</code> 控制能否点击。
        <code>items</code> 是数组（面板不生成控件），每项
        <code>{ src, x, y, width, height, z }</code>。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import PosterCollageSchema from '@melt-js/comps-vue3/src/components/PosterCollage.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const PosterCollage = remoteComponent('PosterCollage')

type Layer = { src: string; x: number; y: number; width: number; height: number; z: number; alt: string }

/** 原 demo 的 12 个位置与层级（设计稿 1400×800） */
const LAYOUT: [string, number, number, number, number, number][] = [
  ['井野', 0, 0, 293, 360, 2],
  ['鹿丸', 705, 435, 337, 365, 3],
  ['小李', 205, 1, 355, 402, 4],
  ['天天', 874, 0, 526, 360, 5],
  ['小樱', 959, 457, 441, 343, 6],
  ['牙', 1032, 254, 368, 308, 7],
  ['志乃', 0, 249, 317, 318, 8],
  ['佐助', 0, 493, 385, 307, 9],
  ['雏田', 502, 0, 447, 360, 10],
  ['丁次', 705, 162, 402, 360, 11],
  ['鸣人', 374, 167, 430, 360, 12],
  ['宁次', 271, 440, 518, 360, 13],
]

const layers: Layer[] = LAYOUT.map(([name, x, y, width, height, z]) => ({
  src: `/poster-collage/${encodeURIComponent(name)}.png`,
  x,
  y,
  width,
  height,
  z,
  alt: name,
}))

/** 原 demo 的白色海报纸张 */
const posterPaper = '#fff'

/** 属性面板使用通用抽象素材，避免把组件能力和具体 IP 绑定在一起 */
const abstractArtwork = `data:image/svg+xml;utf8,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="420" height="360"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#f97316"/><stop offset="1" stop-color="#4c1d95"/></linearGradient></defs><rect x="24" y="24" width="372" height="312" rx="28" fill="url(#g)"/><circle cx="310" cy="112" r="78" fill="white" opacity=".24"/><path d="M20 280 C120 180 180 310 260 220 S360 190 400 250 V340 H20Z" fill="white" opacity=".18"/><text x="78" y="292" fill="white" font-family="Arial" font-size="28" font-weight="700">ABSTRACT</text></svg>')}`
const ABSTRACT_LAYOUT: [string, number, number, number, number, number][] = [
  ['Orbit', 70, 92, 330, 300, 2],
  ['Signal', 300, 18, 380, 320, 4],
  ['Pulse', 570, 132, 360, 320, 6],
  ['Terrain', 860, 40, 430, 340, 8],
  ['Frame', 240, 390, 500, 360, 10],
  ['Echo', 690, 420, 420, 340, 12],
].map(([label, x, y, width, height, z]) => ({ src: abstractArtwork, x, y, width, height, z, alt: label }))

/** 第二块用深色底，突出人物抠图边缘 */
const backdrop = `data:image/svg+xml,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="800"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#101827"/><stop offset="1" stop-color="#2b1a2f"/></linearGradient></defs><rect width="1400" height="800" fill="url(#bg)"/></svg>')}`

const lastSelected = ref('（还没点过）')

const stageStyle = {
  display: 'block',
  height: '560px',
  padding: '16px',
  background: '#f2f4f8',
}

function onSelect(index: number, item: Layer) {
  lastSelected.value = `${item.alt}（第 ${index + 1} 层）`
}
</script>

